query GetOpportunitiesForFinalisation($stepId: String!, $first: Int, $offset: Int) {
  opportunities(
    filters: [{ field: stepId, operation: eq, value: $stepId }]
    first: $first
    offset: $offset
  ) {
    pageInfo {
      hasNextPage
    }
    edges {
      node {
        id
        name
        activeInvoiceId
        salesDocument {
          ... on Invoice {
            id
            lifecycleState
          }
        }
        attributes {
          definitionKey
          value
        }
        interests {
          edges {
            node {
              item {
                __typename
                ... on Event {
                  title
                  startDate
                }
              }
            }
          }
        }
      }
    }
  }
}

