const config = $('Config').first().json;
const now = new Date();
const cutoff = new Date(now.getTime() + Number(config.DAYS_WINDOW) * 24 * 60 * 60 * 1000);

const commentsKey = config.COMMENTS_ATTRIBUTE_KEY;
const poKey = config.PO_REFERENCE_ATTRIBUTE_KEY;

// With pagination on, Get Opportunities returns one item per opportunity edge.
const edges = $input.all().map(item => item.json).filter(edge => edge && edge.node);

return edges
  .filter(({ node }) => {
    const events = (node.interests?.edges || [])
      .filter(e => e.node?.item?.__typename === 'Event')
      .map(e => new Date(e.node.item.startDate))
      .filter(d => !isNaN(d))
      .sort((a, b) => a - b);
    const soonestEvent = events[0];
    return soonestEvent && soonestEvent >= now && soonestEvent <= cutoff;
  })
  .map(({ node }) => {
    const attrs = node.attributes || [];

    const commentsValue = attrs.find(a => a.definitionKey === commentsKey)?.value ?? '';
    const poReferenceValue = attrs.find(a => a.definitionKey === poKey)?.value ?? '';

    return {
      json: {
        id: node.id,
        name: node.name,
        invoiceId: node.activeInvoiceId,
        invoiceState: node.salesDocument?.lifecycleState ?? 'Unknown',
        commentsValue,
        poReferenceValue
      }
    };
  });

