mutation UpdateInvoice($invoiceId: ID!, $comments: String, $purchaseOrderRef: String) {
  invoices {
    update(input: {
      invoiceId: $invoiceId
      comments: $comments
      purchaseOrderRef: $purchaseOrderRef
    }) {
      errors { label message value }
      invoice {
        id
        comments
        purchaseOrderReference
      }
    }
  }
}

mutation FinaliseInvoice($invoiceId: ID!) {
  invoices {
    finalise(input: { invoiceId: $invoiceId }) {
      errors { label message value }
      invoice {
        id
        lifecycleState
        finalisedAt
      }
    }
  }
}

mutation ProgressOpportunityToStep($opportunityId: ID!, $stepId: ID!) {
  opportunities {
    progress(input: {
      opportunityId: $opportunityId
      stepId: $stepId
    }) {
      errors { label message value }
      opportunity {
        id
        name
        step { id name }
      }
    }
  }
}

