const items = $input.all();
const dryRun = $('Config').first().json.DRY_RUN === true;

const moved = items.filter(i => i.json.status === 'moved');
const wouldMove = items.filter(i => i.json.status === 'dryRun');
const errors = items.filter(i => i.json.status === 'error');
const skipped = items.filter(i => i.json.status === 'skipped');

const plural = (count, one, many) => `${count} ${count === 1 ? one : many}`;
const list = (group, withReason) => group
  .map(i => `• *${i.json.name}*${withReason ? ` (${i.json.reason})` : ''}`)
  .join('\n');

const parts = [];

if (dryRun) {
  parts.push('🧪 *Dry run:* no invoices or Opportunities were changed. Set `DRY_RUN` to `false` in Config to apply changes.');
}

if (wouldMove.length > 0) {
  parts.push(`📝 *${plural(wouldMove.length, 'invoice', 'invoices')} WOULD be updated, finalised and moved:*\n` + list(wouldMove, false));
}

if (moved.length > 0) {
  parts.push(`✅ *${plural(moved.length, 'invoice', 'invoices')} updated, finalised and moved:*\n` + list(moved, false));
}

if (errors.length > 0) {
  parts.push(`❌ *${plural(errors.length, 'opportunity', 'opportunities')} failed and need attention:*\n` + list(errors, true));
}

if (skipped.length > 0) {
  parts.push(`⚠️ *${plural(skipped.length, 'opportunity', 'opportunities')} skipped, invoice not in Draft state:*\n` + list(skipped, true));
}

if (items.length === 0) {
  parts.push('No opportunities matched the criteria today.');
}

const message = parts.join('\n\n');

return [{ json: { message, movedCount: moved.length, wouldMoveCount: wouldMove.length, errorCount: errors.length, skippedCount: skipped.length } }];

const item = $('Prepare Item').first().json;

return [{ json: {
  id: item.opportunityId,
  name: item.opportunityName,
  status: 'skipped',
  reason: `Invoice is ${item.invoiceState}, not Draft`
} }];

const item = $('Prepare Item').first().json;

return [{ json: {
  id: item.opportunityId,
  name: item.opportunityName,
  status: 'dryRun',
  reason: 'Would update and finalise the invoice, then move the Opportunity to the target step'
} }];

// Administrate returns HTTP 200 even when a mutation is rejected, so each nested
// errors array is checked explicitly. A request that fails outright arrives as an
// empty item (the mutation nodes continue on error and always output data).
const item = $('Prepare Item').first().json;
const response = $input.first().json || {};
const source = $prevNode.name;

const describe = (errors) => (errors || []).map(e => e.message || e.label).filter(Boolean).join('; ');

let stage = 'Moving the Opportunity';
let result = response.opportunities?.progress;
if (source === 'Update Succeeded?') {
  stage = 'Updating the invoice';
  result = response.invoices?.update;
} else if (source === 'Finalise Succeeded?') {
  stage = 'Finalising the invoice';
  result = response.invoices?.finalise;
}

let status = 'moved';
let reason = `Invoice finalised and moved to ${result?.opportunity?.step?.name ?? 'the target step'}`;

if (!result) {
  status = 'error';
  reason = `${stage} failed: no response returned (see the execution log)`;
} else if ((result.errors || []).length > 0) {
  status = 'error';
  reason = `${stage} failed: ${describe(result.errors)}`;
}

return [{ json: { id: item.opportunityId, name: item.opportunityName, status, reason } }];
